CREATE OR REPLACE VIEW imna.v_rvo_gebied_inrichting AS 
 SELECT ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = g.bron_houder_id)) AS provincie,
    p.rapportage_jaar,
    btrim((g.identificatie)::text) AS identificatie,
    g.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    g.begin_tijd,
    g.eind_tijd,
    g.geom
   FROM (imna.vm_prov_year_gebied_inrichting p
     JOIN imna.gebied_inrichting g ON ((g.id = p.gebied_inrichting_id)));
;

