    ( SELECT btrim((dmn_status_natuur.code)::text) AS btrim
           FROM masterdata.dmn_status_natuur
          WHERE (dmn_status_natuur.id = g.status_natuur_id)) AS status_natuur,
    g.geom
   FROM (imna.vm_prov_year_gebied_natuur p
