CREATE OR REPLACE VIEW imna.v_rvo_voortgangs_rapportage AS 
 SELECT ( SELECT btrim((dmn_provincie_code.code)::text) AS btrim
           FROM masterdata.dmn_provincie_code
          WHERE (dmn_provincie_code.id = g.bron_houder_id)) AS bron_houder,
    p.rapportage_jaar,
    btrim((g.identificatie)::text) AS identificatie,
    g.begin_geldigheid,
    NULL::text AS eind_geldigheid,
    btrim(g.opmerkingen) AS opmerkingen
   FROM (imna.vm_prov_year_voortgangs_rapportage p
     JOIN imna.voortgangs_rapportage g ON ((g.id = p.report_id)));
;
